"""Aggregate C3 (review utility): calibration replicates (PC-7, PC-7c, PC-16,
contract-grid resolving floor, fine-grid E_Sh) and classification replicates
(LEAD counts per planted construction)."""
import json, sys, statistics as st
S = sys.argv[1]
cal = json.load(open(S + '/out/c3_calib.json'))["replicates"]
out = {"calibration_replicates": len(cal), "PC-16": [], "per_lM": {}}
for r in cal:
    out["PC-16"].append({"verdict": r["PC-16"]["verdict"], "L2_interval": [round(x, 3) for x in r["PC-16"]["L2"]["interval"]]})
    for l, c in r["cells"].items():
        for M, x in c.items():
            d = out["per_lM"].setdefault("l=%s,M=%s" % (l, M), {"q50": [], "W": [], "G_key_over_M": [], "PC-7": [], "PC-7c": [],
                                                              "floor_rho_contract_grid": [], "key_Z_median": [], "mix0.5_L1L3": []})
            d["q50"].append(x["null"]["q50"]); d["W"].append(x["null"]["W"])
            d["G_key_over_M"].append(x["G_key_over_M"]); d["PC-7"].append(x["PC-7"]); d["PC-7c"].append(x["PC-7c_pass"])
            d["floor_rho_contract_grid"].append(x["resolving_floor_rho_contract_grid"])
            d["key_Z_median"].append(x["key"]["Z_median"])
            m5 = x["mix_contract_grid"]["0.5"]
            d["mix0.5_L1L3"].append(bool(m5["L1"] and m5["L3"]))
for k, d in out["per_lM"].items():
    out["per_lM"][k] = {"q50_mean": round(st.mean(d["q50"]), 4), "W_mean": round(st.mean(d["W"]), 4),
                        "W_range": [round(min(d["W"]), 4), round(max(d["W"]), 4)],
                        "G_key_over_M_range": [round(min(d["G_key_over_M"]), 4), round(max(d["G_key_over_M"]), 4)],
                        "PC-7_pass": "%d/%d" % (sum(d["PC-7"]), len(d["PC-7"])),
                        "PC-7c_pass": "%d/%d" % (sum(d["PC-7c"]), len(d["PC-7c"])),
                        "key_Z_median_range": [round(min(d["key_Z_median"]), 2), round(max(d["key_Z_median"]), 2)],
                        "floor_rho_on_contract_grid": d["floor_rho_contract_grid"],
                        "mixture_rho_0.5_meets_L1_and_L3": "%d/%d" % (sum(d["mix0.5_L1L3"]), len(d["mix0.5_L1L3"]))}
try:
    cl = json.load(open(S + '/out/c3_classify.json'))["replicates"]
except Exception:
    cl = []
out["classification_replicates"] = len(cl)
tab = {}
for r in cl:
    for a, v in r["verdicts"].items():
        t = tab.setdefault(a, {"verdicts": {}, "L2_holds": 0, "L1L3_all_three": 0, "L2_intervals": [], "Z_by_l": {}})
        t["verdicts"][v["verdict"]] = t["verdicts"].get(v["verdict"], 0) + 1
        t["L2_holds"] += int(v["L2"]["holds"])
        t["L1L3_all_three"] += int(all(pc["L1"] and pc["L3"] for pc in v["per_cell"].values()))
        t["L2_intervals"].append([round(x, 3) for x in v["L2"]["interval"]])
    for a, pcs in r["per_cell"].items():
        for l, s in pcs.items():
            tab[a]["Z_by_l"].setdefault(l, []).append(s["Z_median"])
for a, t in tab.items():
    t["Z_median_mean_by_l"] = {l: round(st.mean(v), 2) for l, v in t["Z_by_l"].items()}
    del t["Z_by_l"]
out["classification"] = tab
print(json.dumps(out, indent=1))

scripts.c3_zladder.py:
"""C3 (review computation). The Z/lZ ladder of CODE-GATE z_ladder (l = 2003,
130873, 2095853; alphabets (16, 8), (64, 16), (128, 32); LEAD alphabets 16,
64, 128) at the declared S, with review seeds (never the contract's).
Arms: the log-interval key i -> floor(i M / l) (PC-7, PC-16); three
relabelled windows (perm[i] >> o) % M with a random bijection perm of Z/l
(PC-7c); the planted mixture of CODE-EST planted_mixture law (the key on a
fraction rho of points, a uniform label on the rest). Decisions by CODE-EST
seed_rows, null_summary, clause_L1/L3, classify_family, imported unchanged.

mode calib: E_Sh(rho) on a fine rho grid at the three LEAD keys (to place
planted filters at a target controlled excess), plus PC-7, PC-7c, the
contract-grid resolving floor and PC-16 on all six (l, M).
mode classify: fixed-rho mixtures across the ladder, and per-cell-rho
planted filters placed at a target multiple of the measured W (flat-Z
floor filters), each classified by classify_family over the three LEAD
keys."""
import sys, json, math, time
import numpy as np
IMPL, SCR = sys.argv[1], sys.argv[2]
sys.path.insert(0, IMPL); sys.path.insert(0, SCR)
import estimator as est
import rt_engine as eng

ZL = ((2003, (16, 8), 16), (130873, (64, 16), 64), (2095853, (128, 32), 128))
CONTRACT_RHOS = (0.5, 0.25, 0.125, 0.0625)


def mixture(key, M, rho, rng):
    keep = rng.random(key.shape[0]) < rho
    return np.where(keep, key, rng.integers(0, M, size=key.shape[0]))


def run_cell(l, Ms, arms_spec, rng, with_relabel=True):
    """arms_spec: dict name -> (M, kind, rho) evaluated at alphabet M."""
    bits = l.bit_length()
    perm = rng.permutation(l)
    Smax = max(est.S_of(M) for M in Ms)
    acc = {M: {"null": [], "arms": {}} for M in Ms}
    for s in range(10):
        P, Q, R = eng.np_stream(l, Smax, rng)
        for M in Ms:
            S = est.S_of(M)
            pre = eng.Prefix(P, Q, R, S)
            acc[M]["null"].extend(eng.null_draws(pre, M, rng, 20))
            key = (pre.uniq * M) // l
            labs = {}
            for name, (MM, kind, rho) in arms_spec.items():
                if MM != M:
                    continue
                if kind == "key":
                    labs[name] = key
                elif kind == "mix":
                    labs[name] = mixture(key, M, rho, rng)
            if with_relabel:
                r = M.bit_length() - 1
                for o in (0, (bits - r) // 2, bits - r):
                    labs["relabel@%d" % o] = (perm[pre.uniq] >> o) % M
            for name, lab in labs.items():
                acc[M]["arms"].setdefault(name, []).append(eng.read_arm(pre, lab, M, rng))
    out = {}
    for M in Ms:
        ns = est.null_summary(acc[M]["null"])
        out[M] = {"null": ns, "rows": {a: est.seed_rows(v, ns) for a, v in acc[M]["arms"].items()}}
    return out


def summarise(rows, ns):
    return {"G_median": est.median([r["G"] for r in rows]),
            "E_RL_median": est.median([r["E_RL"] for r in rows]),
            "E_Sh_median": est.median([r["E_Sh"] for r in rows]),
            "Z_median": est.median([r["Z"] for r in rows]),
            "p_floor_seeds": sum(1 for r in rows if r["p"] <= 1 / 11 + 1e-12),
            "L1": est.clause_L1(rows, ns), "L3": est.clause_L3(rows, ns),
            "estimated": est.estimated(rows)}


def mode_calib(rep, seed_base, fine):
    rng = np.random.default_rng([seed_base, rep])
    res = {"rep": rep, "cells": {}}
    key_cells, lead_keys, log2_ns = {}, [], []
    for l, Ms, leadM in ZL:
        spec = {}
        for M in Ms:
            spec["key@%d" % M] = (M, "key", None)
            for rho in CONTRACT_RHOS:
                spec["mix%g@%d" % (rho, M)] = (M, "mix", rho)
        for rho in fine:
            spec["fine%g@%d" % (rho, leadM)] = (leadM, "mix", rho)
        out = run_cell(l, Ms, spec, rng)
        cres = {}
        for M in Ms:
            ns, rows = out[M]["null"], out[M]["rows"]
            kr = rows["key@%d" % M]
            g_key = est.median([r["G"] for r in kr])
            pc7 = g_key >= M / 3.0 and g_key < M and est.clause_L1(kr, ns) and est.clause_L3(kr, ns)
            pc7c = {a: est.clause_L3(v, ns) for a, v in rows.items() if a.startswith("relabel")}
            floor = None
            for rho in sorted(CONTRACT_RHOS, reverse=True):
                ra = rows["mix%g@%d" % (rho, M)]
                if est.clause_L1(ra, ns) and est.clause_L3(ra, ns):
                    floor = rho
            cres[M] = {"null": ns, "key": summarise(kr, ns), "G_key_over_M": g_key / M, "PC-7": pc7,
                       "PC-7c_L3_by_window": pc7c, "PC-7c_pass": not any(pc7c.values()),
                       "resolving_floor_rho_contract_grid": floor,
                       "mix_contract_grid": {"%g" % rho: summarise(rows["mix%g@%d" % (rho, M)], ns) for rho in CONTRACT_RHOS}}
            if M == leadM:
                cres[M]["fine_grid"] = {"%g" % rho: summarise(rows["fine%g@%d" % (rho, M)], ns) for rho in fine}
            key_cells[("CELL-Z-%d" % l, M)] = {"rows": kr, "null": ns}
        res["cells"][str(l)] = cres
        lead_keys.append(("CELL-Z-%d" % l, leadM))
        log2_ns.append(math.log2(l))
    v = est.classify_family(key_cells, lead_keys, log2_ns)
    res["PC-16"] = {"verdict": v["verdict"], "L2": {"holds": v["L2"]["holds"], "interval": v["L2"]["interval"]}}
    return res


def mode_classify(rep, seed_base, fixed_rhos, planted):
    """planted: name -> {l: rho} per-cell rho placing the median E_Sh at a target."""
    rng = np.random.default_rng([seed_base, 1000 + rep])
    res = {"rep": rep, "verdicts": {}, "per_cell": {}}
    cells_by_arm, lead_keys, log2_ns = {}, [], []
    for l, Ms, leadM in ZL:
        spec = {}
        for rho in fixed_rhos:
            spec["fix%g" % rho] = (leadM, "mix", rho)
        for name, rmap in planted.items():
            spec[name] = (leadM, "mix", rmap[str(l)])
        out = run_cell(l, (leadM,), spec, rng, with_relabel=False)
        ns, rows = out[leadM]["null"], out[leadM]["rows"]
        for a, rr in rows.items():
            cells_by_arm.setdefault(a, {})[("CELL-Z-%d" % l, leadM)] = {"rows": rr, "null": ns}
            res["per_cell"].setdefault(a, {})[str(l)] = summarise(rr, ns)
        lead_keys.append(("CELL-Z-%d" % l, leadM))
        log2_ns.append(math.log2(l))
    for a, cm in cells_by_arm.items():
        v = est.classify_family(cm, lead_keys, log2_ns)
        res["verdicts"][a] = {"verdict": v["verdict"], "L2": {"holds": v["L2"]["holds"], "interval": v["L2"]["interval"], "slopes": v["L2"]["slopes"]},
                              "per_cell": {"%s@%d" % k: pc for k, pc in v["per_cell"].items()}}
    return res


if __name__ == "__main__":
    mode, rep0, nrep, seed_base, outp = sys.argv[3], int(sys.argv[4]), int(sys.argv[5]), int(sys.argv[6]), sys.argv[7]
    allr, t0 = [], time.time()
    for rep in range(rep0, rep0 + nrep):
        if mode == "calib":
            fine = [1.0, 0.9, 0.8, 0.7, 0.6, 0.5, 0.45, 0.4, 0.35, 0.3, 0.25, 0.2]
            allr.append(mode_calib(rep, seed_base, fine))
        else:
            cfg = json.load(open(sys.argv[8]))
            allr.append(mode_classify(rep, seed_base, cfg["fixed_rhos"], cfg["planted"]))
        json.dump({"mode": mode, "replicates": allr, "elapsed_s": time.time() - t0}, open(outp, "w"),
                  default=lambda o: o.item() if isinstance(o, (np.integer, np.floating)) else str(o))
    print("done", mode, nrep, "in %.1f s" % (time.time() - t0))

scripts.pdftext.py:
"""Minimal PDF text extraction (review utility): inflate FlateDecode streams
and pull the string operands of Tj/TJ/'/" text operators. No external libs."""
import re, sys, zlib
data = open(sys.argv[1], 'rb').read()
out = []
for m in re.finditer(rb'stream\r?\n', data):
    start = m.end()
    end = data.find(b'endstream', start)
    if end < 0:
        continue
    raw = data[start:end]
    try:
        dec = zlib.decompress(raw)
    except Exception:
        try:
            dec = zlib.decompressobj().decompress(raw)
        except Exception:
            continue
    if b'BT' not in dec:
        continue
    for bt in re.finditer(rb'BT(.*?)ET', dec, re.S):
        seg = bt.group(1)
        line = []
        for tm in re.finditer(rb'\[(.*?)\]\s*TJ|\((.*?)(?<!\\)\)\s*Tj|(T\*|Td|TD|Tm)', seg, re.S):
            if tm.group(1) is not None:
                for s in re.finditer(rb'\((.*?)(?<!\\)\)|(-?\d+\.?\d*)', tm.group(1), re.S):
                    if s.group(1) is not None:
                        line.append(s.group(1))
                    elif s.group(2) is not None and float(s.group(2)) < -200:
                        line.append(b' ')
            elif tm.group(2) is not None:
                line.append(tm.group(2))
            else:
                line.append(b'\n')
        txt = b''.join(line)
        txt = txt.replace(b'\\(', b'(').replace(b'\\)', b')').replace(b'\\\\', b'\\')
        out.append(txt.decode('latin-1'))
print('\n'.join(out))

scripts.extract.py:
import yaml, hashlib, sys, os
S = sys.argv[1]
with open(os.path.join(S, 'bound/audit.yaml'), 'rb') as f:
    raw = f.read()
print('audit sha256', hashlib.sha256(raw).hexdigest())
d = yaml.safe_load(raw)
def find_code_blocks(o, path=''):
    out = []
    if isinstance(o, dict):
        if 'code' in o and isinstance(o.get('code'), str):
            out.append((path, o))
        for k, v in o.items():
            out.extend(find_code_blocks(v, path + '/' + str(k)))
    elif isinstance(o, list):
        for i, v in enumerate(o):
            out.extend(find_code_blocks(v, path + '[%d]' % i))
    return out
blocks = find_code_blocks(d)
for path, b in blocks:
    code = b['code']
    h = hashlib.sha256(code.encode('utf-8')).hexdigest()
    keys = [k for k in b.keys() if k != 'code']
    print(path, b.get('id'), b.get('file'), 'sha', h, 'ref', b.get('reference_sha256'), 'match', h == b.get('reference_sha256'), 'keys', keys)
    fn = b.get('file') or (str(b.get('id')) + '.py')
    with open(os.path.join(S, 'impl', fn), 'w', encoding='utf-8') as g:
        g.write(code)
